import{at as e,n as t,rt as n,yt as r}from"./chunks/framework.ne95vkW4.js";var i=JSON.parse(`{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1790003582000}`),a={name:`getting-started/installation.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>This guide gets <code>emgr</code> running locally - from a fresh clone, through the two startup checks that fail closed by design, to a working <code>/health</code> response.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><ul><li>A stable Rust toolchain. <code>Cargo.toml</code> sets <code>edition = &quot;2024&quot;</code>, which needs Rust 1.85 or newer; CI builds against whatever <code>dtolnay/rust-toolchain@stable</code> currently resolves to, so there&#39;s no lower pin to target beyond that. Nothing else: <code>emgr</code> has no C or C++ dependencies (#134), so there&#39;s no native toolchain to install (<code>nasm</code>, <code>cmake</code>, <code>meson</code>, <code>ninja-build</code> used to be required here, for <code>mozjpeg-sys</code>/<code>libavif-sys</code>&#39;s vendored C builds; a <code>no-native-deps</code> CI job now fails the build if any dependency reintroduces one). <code>cargo build</code> is a self-contained Rust build on every supported target.</li><li><a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">Docker</a> and <a href="https://docs.docker.com/compose/" target="_blank" rel="noreferrer">Docker Compose</a> v2 (optional - see <a href="./../deployment/docker">Docker deployment</a>).</li><li><a href="https://kubernetes.io/docs/setup/" target="_blank" rel="noreferrer">Kubernetes</a> and <a href="https://helm.sh/docs/intro/install/" target="_blank" rel="noreferrer">Helm</a> 3 (optional - see the <a href="./../deployment/helm-chart">Helm chart</a> guide).</li></ul><h2 id="clone-the-repository" tabindex="-1">Clone the repository <a class="header-anchor" href="#clone-the-repository" aria-label="Permalink to “Clone the repository”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/vaam-store/image-resizer.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image-resizer</span></span></code></pre></div><p>A fresh clone builds with plain <code>cargo build</code> - no code generation step, no Docker step. <code>make init</code> (an old OpenAPI-codegen bootstrap) and the <code>openapi.yaml</code>/<code>packages/gen-server</code> it drove no longer exist: the HTTP router in <code>src/modules/api</code>, <code>src/modules/router</code> and <code>src/modules/url</code> is hand-written (removed in <a href="https://github.com/vaam-store/image-resizer/issues/53" target="_blank" rel="noreferrer">GH #53</a>).</p><h2 id="pick-a-feature-set" tabindex="-1">Pick a feature set <a class="header-anchor" href="#pick-a-feature-set" aria-label="Permalink to “Pick a feature set”">​</a></h2><p><code>Cargo.toml</code> sets <code>default = []</code>. That&#39;s deliberate, but it means a bare <code>cargo build</code> compiles fine and then the binary refuses to start:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: No storage features are enabled</span></span></code></pre></div><p>Every build must name at least one storage backend explicitly, from <code>Cargo.toml</code>&#39;s <code>[features]</code>:</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th></tr></thead><tbody><tr><td><code>local_fs</code></td><td>Store resized images on local disk. No external dependency - the easiest way to get started.</td></tr><tr><td><code>s3</code></td><td>Store resized images in S3 or an S3-compatible service (MinIO). Needs a reachable endpoint - see <a href="./../deployment/docker">Docker deployment</a> for a MinIO-backed <code>compose.yaml</code> setup.</td></tr><tr><td><code>in_memory</code></td><td>An in-process cache. Only reachable in this crate&#39;s own test builds (<a href="https://github.com/vaam-store/image-resizer/issues/39" target="_blank" rel="noreferrer">GH #39</a>) - selecting it in a release build falls through to the same &quot;no storage backend&quot; error above. Useful for <code>cargo test</code>, not for running the service.</td></tr><tr><td><code>otel</code></td><td>OpenTelemetry tracing + a Prometheus <code>/metrics</code> endpoint. Combine with a storage feature, e.g. <code>local_fs,otel</code>.</td></tr></tbody></table><p>You can enable more than one storage feature in the same binary - see <code>STORAGE_TYPE</code> in <a href="./configuration">Configuration</a> for how the backend is then chosen at runtime.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Build with local filesystem storage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local_fs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Build with S3/MinIO storage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Build with local filesystem storage plus tracing/metrics</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local_fs,otel</span></span></code></pre></div><p><code>--no-default-features</code> is a no-op today (<code>default = []</code>), but CI always passes it explicitly so these stay genuinely isolated feature sets if a non-empty default is ever added later - worth doing the same locally.</p><h2 id="configure-the-two-startup-checks" tabindex="-1">Configure the two startup checks <a class="header-anchor" href="#configure-the-two-startup-checks" aria-label="Permalink to “Configure the two startup checks”">​</a></h2><p>Both of these are enforced in <code>ApiService::create</code> at process startup, not per-request - a misconfigured deployment is refused outright rather than serving broken responses.</p><h3 id="_1-signed-urls-always-required" tabindex="-1">1. Signed URLs (always required) <a class="header-anchor" href="#_1-signed-urls-always-required" aria-label="Permalink to “1. Signed URLs (always required)”">​</a></h3><p>Signing is the default, not opt-in (<a href="https://github.com/vaam-store/image-resizer/issues/27" target="_blank" rel="noreferrer">GH #27</a>). <code>emgr</code> refuses to start unless <strong>both</strong> <code>SIGNING_KEY</code> and <code>SIGNING_SALT</code> (hex-encoded) are set, <strong>or</strong> you explicitly opt out:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Real key/salt (recommended, even for local dev)</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SIGNING_KEY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SIGNING_SALT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Or, explicitly opt out for local development only:</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ALLOW_UNSIGNED_REQUESTS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span></code></pre></div><p>With <code>ALLOW_UNSIGNED_REQUESTS=true</code>, a request whose signature segment is the literal <code>unsigned</code> bypasses verification. It never weakens verification of a real signature - it only widens that one escape path. See <a href="./configuration">Configuration</a> and the <a href="./../user-guide/api-reference">API reference</a> for the signed-URL format, and <a href="./../user-guide/examples">Examples</a> for computing a real signature.</p><h3 id="_2-metrics-authentication-otel-builds-only" tabindex="-1">2. <code>/metrics</code> authentication (<code>otel</code> builds only) <a class="header-anchor" href="#_2-metrics-authentication-otel-builds-only" aria-label="Permalink to “2. /metrics authentication (otel builds only)”">​</a></h3><p>If (and only if) the binary was built with <code>--features otel</code>, a second, independent check applies: <code>emgr</code> refuses to start unless <code>METRICS_AUTH_TOKEN</code> is set, <strong>or</strong> you explicitly opt out with <code>ALLOW_UNAUTHENTICATED_METRICS=true</code> (<a href="https://github.com/vaam-store/image-resizer/issues/77" target="_blank" rel="noreferrer">GH #77</a>). <code>/metrics</code> exposes request rates, cache hit ratios, error counts and latency histograms - reconnaissance-grade information about the service&#39;s traffic - so this fails closed exactly like signing does.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> METRICS_AUTH_TOKEN</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Or: export ALLOW_UNAUTHENTICATED_METRICS=true</span></span></code></pre></div><p>A non-<code>otel</code> build has no <code>/metrics</code> endpoint at all and doesn&#39;t require either variable. <code>/health</code> is unauthenticated on both builds - orchestrator probes can&#39;t easily carry a secret.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOCAL_FS_STORAGE_PATH</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">./data/images</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ALLOW_UNSIGNED_REQUESTS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true   </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># or the real SIGNING_KEY/SIGNING_SALT above</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local_fs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> emgr</span></span></code></pre></div><p><code>--bin emgr</code> is required - the crate also ships <code>healthcheck</code> (the Docker <code>HEALTHCHECK</code> binary) and <code>benchmark</code> (an HTTP load-test tool, see <a href="./../development/testing">Testing</a>), so <code>cargo run</code> alone can&#39;t guess which one you mean.</p><p>By default the service listens on <code>0.0.0.0:3000</code> (<code>HOST</code> / <code>PORT</code>):</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000/health</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>content-type: text/plain; charset=utf-8</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OK</span></span></code></pre></div><p>For the full environment variable reference (storage backend selection, the SSRF source-fetch guard, resolution limits, performance tuning, observability), see <a href="./configuration">Configuration</a> - it&#39;s generated against <code>src/modules/env/env.rs</code> and CI-checked for drift.</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to “Docker”">​</a></h2><p>See <a href="./../deployment/docker">Docker deployment</a> for the four build targets (<code>fs_deploy</code>, <code>fs_otel_deploy</code>, <code>s3_deploy</code>, <code>s3_otel_deploy</code>) and <code>compose.yaml</code>.</p><h2 id="kubernetes" tabindex="-1">Kubernetes <a class="header-anchor" href="#kubernetes" aria-label="Permalink to “Kubernetes”">​</a></h2><p>See the <a href="./../deployment/helm-chart">Helm chart</a> guide for deploying to Kubernetes.</p>`,36)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};